                  currentPage === item.page
                    ? 'bg-gradient-to-r from-pink-50 to-purple-50 text-pink-600 shadow-sm border border-pink-100'
                    : 'text-slate-500 hover:bg-pink-50 hover:text-pink-500'
                }`}
              >
                <item.icon className={`w-5 h-5 transition-colors ${currentPage === item.page ? 'text-pink-500' : 'text-slate-300 group-hover:text-pink-400'}`} />
                {item.label}
              </button>
            ))}
          </div>

          <div className="pt-6 border-t border-pink-50">
             <div className="bg-gradient-to-br from-pink-500 to-rose-400 rounded-3xl p-5 text-white shadow-xl shadow-pink-200 mb-6 relative overflow-hidden group">
                <div className="absolute top-0 right-0 -mt-2 -mr-2 w-16 h-16 bg-white/20 rounded-full blur-xl group-hover:scale-150 transition-transform"></div>
                <h4 className="font-bold relative z-10">Premium Plan</h4>
                <p className="text-xs text-pink-100 mt-1 relative z-10 opacity-90">Unlock unlimited AI coaching today!</p>
                <button className="mt-3 bg-white text-pink-600 text-xs font-bold py-2 px-4 rounded-full shadow-sm hover:bg-pink-50 transition-colors relative z-10">
                    Upgrade Now
                </button>
             </div>

             <button className="w-full flex items-center gap-4 px-5 py-3 rounded-2xl text-slate-400 hover:text-rose-500 hover:bg-rose-50 transition-colors font-medium">
               <LogOut className="w-5 h-5" />
               <span>Log Out</span>
             </button>
          </div>
        </div>
      </div>

      {/* Overlay for mobile */}
      {isMobileOpen && (
        <div 
          className="fixed inset-0 bg-purple-900/20 backdrop-blur-sm z-30 lg:hidden"
