export default Navigation;

import React, { useState, useEffect } from 'react';
import { Workout, ExerciseType, Set as WorkoutSet, Exercise, ExerciseDefinition } from '../types';
import { Clock, CheckCircle2, Circle, Edit2, Plus, Trash2, X, Trophy, Sparkles, TrendingUp, Share2, ArrowRight, Zap, PartyPopper, Timer, Heart } from 'lucide-react';
import ExerciseLibrary from './ExerciseLibrary';

interface WorkoutCardProps {
  workout: Workout;
  history?: Workout[];
  onToggleComplete: (id: string) => void;
  onUpdateWorkout: (updatedWorkout: Workout) => void;
  onDeleteWorkout: (id: string) => void;
}

const ConfettiPiece = ({ delay, color }: { delay: number; color: string }) => {
  const randomX = (Math.random() - 0.5) * 400; // -200 to 200px
  const randomY = (Math.random() - 0.5) * 400; // -200 to 200px
  const randomRotate = Math.random() * 360;

  const style = {
    '--tx': `${randomX}px`,
    '--ty': `${randomY}px`,
    '--rot': `${randomRotate}deg`,
    animationDelay: `${delay}ms`,
    backgroundColor: color,
  } as React.CSSProperties;

  return <div className="confetti-particle" style={style} />;
};

const CelebrationOverlay = () => {
  const [progress, setProgress] = useState(0);
  const colors = ['#ec4899', '#f472b6', '#a855f7', '#fb7185', '#34d399']; // Pink, Rose, Purple, Teal

  useEffect(() => {
    // Animate progress bar
    const timer = setTimeout(() => setProgress(100), 100);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-white/95 backdrop-blur-md rounded-[2rem] animate-fade-in overflow-hidden border border-pink-100">
      <style>
        {`
          @keyframes confetti-burst {
            0% { transform: translate(-50%, -50%) scale(0); opacity: 1; }
            70% { opacity: 1; }
            100% { transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) rotate(var(--rot)); opacity: 0; }
          }
          .confetti-particle {
            position: absolute;
            top: 50%;
            left: 50%;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            animation: confetti-burst 1.5s ease-out forwards;
            pointer-events: none;
          }
        `}
      </style>

      {/* Confetti Explosion */}
      {Array.from({ length: 40 }).map((_, i) => (
        <ConfettiPiece 
          key={i} 
          delay={Math.random() * 200} 
          color={colors[Math.floor(Math.random() * colors.length)]} 
        />
      ))}

      <div className="relative z-10 flex flex-col items-center animate-bounce-in text-center p-6">
        <div className="relative mb-6">
           <Trophy className="w-24 h-24 text-yellow-400 fill-yellow-200 drop-shadow-xl animate-bounce" />
           <Sparkles className="absolute -top-4 -right-4 w-10 h-10 text-pink-500 animate-pulse" />
           <Heart className="absolute -bottom-2 -left-4 w-8 h-8 text-rose-500 fill-rose-500 animate-pulse delay-150" />
        </div>

        <h3 className="text-3xl font-black text-transparent bg-clip-text bg-gradient-to-r from-pink-500 to-purple-600 mb-2">
           SLAYED IT!
        </h3>
        <p className="text-slate-500 font-bold mb-6">Another workout crushed, queen! 👑</p>

        {/* Progress/Sync Bar */}
        <div className="w-64 space-y-2">
            <div className="flex justify-between text-xs font-bold text-pink-300 uppercase tracking-wider">
                <span>Saving Gains</span>
                <span>{progress === 100 ? '✨ Done' : 'Syncing...'}</span>
            </div>
            <div className="h-3 bg-pink-50 rounded-full overflow-hidden shadow-inner border border-pink-100">
                <div 
                    className="h-full bg-gradient-to-r from-pink-400 to-purple-500 transition-all duration-1000 ease-out rounded-full"
                    style={{ width: `${progress}%` }}
                />
            </div>
        </div>
      </div>
    </div>
  );
};

const WorkoutCard: React.FC<WorkoutCardProps> = ({ workout, history = [], onToggleComplete, onUpdateWorkout, onDeleteWorkout }) => {
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState(workout.title);
  const [showCelebration, setShowCelebration] = useState(false);
  const [isLibraryOpen, setIsLibraryOpen] = useState(false);

  // Timer State
  const [restTimer, setRestTimer] = useState(0);
  const [isTimerActive, setIsTimerActive] = useState(false);

  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isTimerActive && restTimer > 0) {
      interval = setInterval(() => {
        setRestTimer((prev) => prev - 1);
      }, 1000);
    } else if (restTimer <= 0) {
      setIsTimerActive(false);
    }
    return () => clearInterval(interval);
  }, [isTimerActive, restTimer]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const startRestTimer = (seconds: number = 90) => {
    setRestTimer(seconds);
    setIsTimerActive(true);
  };

  const adjustTimer = (seconds: number) => {
    setRestTimer(prev => Math.max(0, prev + seconds));
  };

  const saveTitle = () => {
    onUpdateWorkout({ ...workout, title: editedTitle });
    setIsEditingTitle(false);
  };

  const handleToggleClick = () => {
    if (!workout.completed) {
        setShowCelebration(true);
        // Extended duration for the elaborate animation
        setTimeout(() => {
            setShowCelebration(false);
            onToggleComplete(workout.id);
        }, 3000); 
    } else {
        onToggleComplete(workout.id);
    }
  };

  const handleShare = async () => {
    const text = `I just crushed my "${workout.title}" workout on PowHER Lifts! 💪✨\nDuration: ${workout.durationMinutes} mins\n#PowHERLifts #FitnessGoal`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: 'PowHER Lifts Workout',
          text: text,
          url: window.location.href // Optional: link to the app
        });
      } catch (err) {
        console.error('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(text);
      alert('Workout summary copied to clipboard! Ready to share on your socials. 🚀');
    }
  };

  // Exercise Handlers
  const handleUpdateExerciseName = (exIndex: number, name: string) => {
    const updatedExercises = [...workout.exercises];
    updatedExercises[exIndex].name = name;
    onUpdateWorkout({ ...workout, exercises: updatedExercises });
  };

  const handleDeleteExercise = (exIndex: number) => {
    const updatedExercises = workout.exercises.filter((_, i) => i !== exIndex);
    onUpdateWorkout({ ...workout, exercises: updatedExercises });
  };

  const handleSelectExercise = (exerciseDef: ExerciseDefinition) => {
    const newExercise: Exercise = {
      id: Date.now().toString(),
      name: exerciseDef.name,
      type: exerciseDef.type,
      sets: [
        { id: Date.now().toString() + '-1', reps: 10, weight: 0, completed: false }
      ],
      notes: exerciseDef.description
    };
    onUpdateWorkout({ ...workout, exercises: [...workout.exercises, newExercise] });
    setIsLibraryOpen(false);
  };

  const handleAddCustomExercise = () => {
    const newExercise: Exercise = {
      id: Date.now().toString(),
      name: 'New Exercise',
      type: ExerciseType.STRENGTH,
      sets: [
        { id: Date.now().toString() + '-1', reps: 10, weight: 0, completed: false }
      ]
    };
    onUpdateWorkout({ ...workout, exercises: [...workout.exercises, newExercise] });
    setIsLibraryOpen(false);
  };

  // Set Handlers
  const handleUpdateSet = (exIndex: number, setIndex: number, field: keyof WorkoutSet, value: number) => {
    const updatedExercises = [...workout.exercises];
    // @ts-ignore
    updatedExercises[exIndex].sets[setIndex][field] = value;
    onUpdateWorkout({ ...workout, exercises: updatedExercises });
  };

  const handleToggleSetComplete = (exIndex: number, setIndex: number) => {
    const updatedExercises = [...workout.exercises];
    const isNowComplete = !updatedExercises[exIndex].sets[setIndex].completed;
    updatedExercises[exIndex].sets[setIndex].completed = isNowComplete;

    onUpdateWorkout({ ...workout, exercises: updatedExercises });

    // Auto-start rest timer on completion
    if (isNowComplete) {
      startRestTimer(90);
    }
  };

  const handleAddSet = (exIndex: number) => {
    const updatedExercises = [...workout.exercises];
    const previousSet = updatedExercises[exIndex].sets[updatedExercises[exIndex].sets.length - 1];
    updatedExercises[exIndex].sets.push({
      id: Date.now().toString(),
      reps: previousSet ? previousSet.reps : 10,
      weight: previousSet ? previousSet.weight : 0,
      completed: false
    });
    onUpdateWorkout({ ...workout, exercises: updatedExercises });
  };

  const handleDeleteSet = (exIndex: number, setIndex: number) => {
    const updatedExercises = [...workout.exercises];
    if (updatedExercises[exIndex].sets.length > 1) {
      updatedExercises[exIndex].sets.splice(setIndex, 1);
      onUpdateWorkout({ ...workout, exercises: updatedExercises });
    }
  };

  const applySuggestion = (exIndex: number, weight: number, reps: number) => {
    const updatedExercises = [...workout.exercises];
    updatedExercises[exIndex].sets = updatedExercises[exIndex].sets.map(s => ({
        ...s,
        weight: weight,
        reps: reps
    }));
    onUpdateWorkout({ ...workout, exercises: updatedExercises });
  };

  // Logic to find previous best stats
  const getPreviousStats = (exerciseName: string) => {
    if (!history.length) return null;

    // Sort history by date descending to find the most recent
    const sortedHistory = [...history].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // Find the most recent COMPLETED workout that contains this exercise
    const previousWorkout = sortedHistory.find(h => 
        h.id !== workout.id && 
        h.completed &&
        h.exercises.some(e => e.name.trim().toLowerCase() === exerciseName.trim().toLowerCase())
    );

    if (!previousWorkout) return null;

    const previousExercise = previousWorkout.exercises.find(e => e.name.trim().toLowerCase() === exerciseName.trim().toLowerCase());

    let maxWeight = 0;
    let maxReps = 0;

    if (previousExercise) {
        previousExercise.sets.forEach(s => {
            if (s.completed && s.weight > maxWeight) {
                maxWeight = s.weight;
                maxReps = s.reps;
            }
        });
    }

    if (maxWeight > 0) {
        return { weight: maxWeight, reps: maxReps };
    }
    return null;
  };

  return (
    <div className={`relative bg-white rounded-[2rem] shadow-xl shadow-pink-100/50 border border-pink-100 p-6 transition-all duration-300 hover:shadow-2xl hover:shadow-pink-200/50 ${workout.completed ? 'border-pink-200 bg-pink-50/30' : ''}`}>

      {/* Celebration Overlay */}
      {showCelebration && <CelebrationOverlay />}

      {/* Floating Rest Timer */}
      {isTimerActive && (
        <div className="fixed bottom-6 right-6 bg-slate-900/90 backdrop-blur-md text-white p-5 rounded-3xl shadow-2xl z-50 flex items-center gap-6 animate-bounce-in border border-slate-700">
            <div className="flex flex-col">
                <span className="text-[10px] text-pink-300 font-bold uppercase tracking-widest flex items-center gap-1">
                    <Timer className="w-3 h-3" /> Rest Timer
                </span>
                <span className="text-3xl font-mono font-bold text-white tabular-nums leading-none mt-1">{formatTime(restTimer)}</span>
            </div>
            <div className="flex items-center gap-2">
                <button 
                  onClick={() => adjustTimer(-10)} 
                  className="px-3 py-1.5 hover:bg-white/10 rounded-xl text-xs font-bold text-slate-300 transition-colors"
                >
                  -10s
                </button>
                <button 
                  onClick={() => adjustTimer(30)} 
                  className="px-3 py-1.5 bg-pink-500 hover:bg-pink-600 rounded-xl text-xs font-bold text-white transition-colors shadow-lg shadow-pink-500/30"
                >
                  +30s
                </button>
                <div className="w-px h-6 bg-white/10 mx-1"></div>
                <button 
                  onClick={() => setIsTimerActive(false)} 
                  className="p-2 hover:bg-white/10 rounded-full text-slate-400 hover:text-red-400 transition-colors"
                  title="Stop Timer"
                >
                  <X className="w-5 h-5" />
                </button>
            </div>
        </div>
      )}

      {/* Header */}
      <div className={`flex justify-between items-start mb-6 ${workout.completed && !showCelebration ? 'opacity-75' : ''}`}>
        <div className="flex-1 mr-4">
          {isEditingTitle ? (
            <input 
              autoFocus
              type="text" 
              value={editedTitle}
              onChange={(e) => setEditedTitle(e.target.value)}
              onBlur={saveTitle}
              onKeyDown={(e) => e.key === 'Enter' && saveTitle()}
              className="text-xl font-black text-slate-900 bg-transparent border-b-2 border-pink-500 focus:outline-none w-full"
            />
          ) : (
            <div className="flex items-center gap-2 group">
              <h3 
                className="text-xl font-black text-slate-900 cursor-pointer group-hover:text-pink-600 transition-colors"
                onClick={() => setIsEditingTitle(true)}
              >
                {workout.title}
              </h3>
              <Edit2 
                className="w-4 h-4 text-slate-300 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer text-pink-400" 
                onClick={() => setIsEditingTitle(true)}
              />
            </div>
          )}
          <div className="flex items-center gap-3 mt-2 text-xs text-slate-500 font-bold">
             <span className="flex items-center gap-1 bg-pink-50 text-pink-600 px-3 py-1.5 rounded-full border border-pink-100">
               <Clock className="w-3 h-3" /> {workout.durationMinutes > 0 ? `${workout.durationMinutes} min` : 'Plan'}
             </span>
             <span className="flex items-center gap-1 bg-purple-50 text-purple-600 px-3 py-1.5 rounded-full border border-purple-100">
               <Dumbbell className="w-3 h-3" /> {workout.exercises.length} Exercises
             </span>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {/* Manual Timer Toggle */}
          <button 
            onClick={() => isTimerActive ? setIsTimerActive(false) : startRestTimer(90)}
            className={`p-2.5 rounded-full transition-all ${isTimerActive ? 'bg-pink-100 text-pink-600' : 'text-slate-400 hover:text-pink-600 hover:bg-pink-50'}`}
            title={isTimerActive ? "Stop Timer" : "Start 90s Rest"}
          >
            <Timer className="w-5 h-5" />
          </button>

          {workout.completed && (
            <button 
              onClick={handleShare}
              className="p-2.5 text-slate-400 hover:text-pink-600 hover:bg-pink-50 rounded-full transition-all"
              title="Share Workout"
            >
              <Share2 className="w-5 h-5" />
            </button>
          )}
          <button 
            onClick={handleToggleClick}
            className={`
              flex items-center justify-center w-11 h-11 rounded-full transition-all duration-300 transform active:scale-95
              ${workout.completed 
                ? 'bg-gradient-to-r from-pink-500 to-rose-500 text-white shadow-lg shadow-pink-200' 
                : 'bg-slate-100 text-slate-300 hover:bg-slate-200 hover:text-slate-400'}
            `}
          >
            {workout.completed ? <CheckCircle2 className="w-6 h-6" /> : <Circle className="w-6 h-6" />}
          </button>
          <button 
            onClick={() => onDeleteWorkout(workout.id)}
            className="p-2.5 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-full transition-colors"
          >
             <Trash2 className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Exercises List */}
      <div className={`space-y-6 ${workout.completed && !showCelebration ? 'opacity-50 pointer-events-none select-none grayscale-[0.2]' : ''}`}>
        {workout.exercises.map((exercise, exIndex) => {
          const prevStats = getPreviousStats(exercise.name);
          const suggestion = prevStats ? { weight: prevStats.weight + 5, reps: prevStats.reps } : null;

          return (
            <div key={exercise.id} className="space-y-3">
              <div className="flex justify-between items-center border-b border-pink-50 pb-2">
                 <div className="flex flex-col w-full">
                   <input 
                     type="text"
                     value={exercise.name}
                     onChange={(e) => handleUpdateExerciseName(exIndex, e.target.value)}
                     className="font-bold text-slate-800 bg-transparent focus:outline-none focus:text-pink-600 w-full text-sm sm:text-base placeholder-slate-300"
                     placeholder="Exercise Name"
                   />
                   {suggestion && !workout.completed && (
                     <div className="flex items-center gap-2 mt-1">
                        <div className="flex items-center gap-1 text-[10px] text-purple-600 font-bold animate-pulse">
                            <TrendingUp className="w-3 h-3" />
                            Goal: {suggestion.weight}lbs x {suggestion.reps}
                        </div>
                        <button 
                            onClick={() => applySuggestion(exIndex, suggestion.weight, suggestion.reps)}
                            className="flex items-center gap-1 px-2 py-0.5 text-[10px] bg-purple-50 text-purple-600 hover:bg-purple-100 rounded-full transition-colors font-bold"
                            title="Apply to all sets"
                        >
                            Apply <ArrowRight className="w-2 h-2" />
                        </button>
                     </div>
                   )}
                 </div>
                 <button onClick={() => handleDeleteExercise(exIndex)} className="text-slate-300 hover:text-rose-400 p-1">
                    <X className="w-4 h-4" />
                 </button>
              </div>

              <div className="space-y-2">
                <div className="grid grid-cols-10 gap-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest text-center mb-1">
                   <div className="col-span-2">Set</div>
                   <div className="col-span-3">Lbs</div>
                   <div className="col-span-3">Reps</div>
                   <div className="col-span-2">Done</div>
                </div>
                {exercise.sets.map((set, setIndex) => {
                  // Determine if this set is an "Overload" set (better than previous best)
                  const isOverload = set.completed && prevStats && (
                    set.weight > prevStats.weight || 
                    (set.weight === prevStats.weight && set.reps > prevStats.reps)
                  );

                  return (
                    <div 
                        key={set.id} 
                        className={`grid grid-cols-10 gap-2 items-center rounded-xl p-1 transition-colors ${isOverload ? 'bg-yellow-50/80 ring-1 ring-yellow-100' : ''}`}
                    >
                        <div className="col-span-2 flex justify-center">
                        <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${isOverload ? 'bg-yellow-100 text-yellow-600' : 'bg-pink-50 text-pink-400'}`}>
                            {setIndex + 1}
                        </div>
                        </div>
                        <div className="col-span-3">
                        <input 
                            type="number" 
                            value={set.weight}
                            onChange={(e) => handleUpdateSet(exIndex, setIndex, 'weight', Number(e.target.value))}
                            className={`w-full bg-slate-50 hover:bg-white rounded-lg py-1.5 px-2 text-center text-sm font-bold focus:ring-2 focus:ring-pink-200 focus:outline-none transition-all ${isOverload ? 'text-yellow-600' : 'text-slate-700'}`}
                        />
                        </div>
                        <div className="col-span-3">
                        <input 
                            type="number" 
                            value={set.reps}
                            onChange={(e) => handleUpdateSet(exIndex, setIndex, 'reps', Number(e.target.value))}
                            className="w-full bg-slate-50 hover:bg-white rounded-lg py-1.5 px-2 text-center text-sm font-bold text-slate-700 focus:ring-2 focus:ring-pink-200 focus:outline-none transition-all"
                        />
                        </div>
                        <div className="col-span-2 flex justify-center gap-1 group/set relative">
                        {isOverload && (
                           <div className="absolute -left-6 top-1 animate-pulse" title="Progressive Overload!">
                              <Zap className="w-4 h-4 text-yellow-500 fill-yellow-500" />
                           </div>
                        )}
                        <button 
                            onClick={() => handleToggleSetComplete(exIndex, setIndex)}
                            className={`
                            w-7 h-7 rounded-lg flex items-center justify-center transition-all
                            ${set.completed ? 'bg-gradient-to-br from-pink-500 to-rose-500 text-white shadow-md shadow-pink-200' : 'bg-slate-100 text-slate-300 hover:bg-pink-100 hover:text-pink-400'}
                            `}
                        >
                            <CheckCircle2 className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleDeleteSet(exIndex, setIndex)}
                            className="opacity-0 group-hover/set:opacity-100 text-slate-300 hover:text-rose-400 transition-opacity absolute -right-5"
                        >
                            <X className="w-4 h-4" />
                        </button>
                        </div>
                    </div>
                  );
                })}
                <button 
                  onClick={() => handleAddSet(exIndex)}
                  className="w-full py-2 flex items-center justify-center gap-2 text-xs font-bold text-pink-300 hover:text-pink-500 hover:bg-pink-50 rounded-xl border border-dashed border-pink-100 hover:border-pink-300 transition-all mt-2"
                >
                   <Plus className="w-3 h-3" /> Add Set
                </button>
              </div>
            </div>
          );
        })}
      </div>

      <button 
         onClick={() => setIsLibraryOpen(true)}
         className={`w-full mt-6 py-3.5 flex items-center justify-center gap-2 font-bold text-pink-500 bg-pink-50/50 hover:bg-pink-50 hover:text-pink-600 hover:shadow-md hover:shadow-pink-100 rounded-2xl border border-pink-100 transition-all ${workout.completed ? 'hidden' : ''}`}
      >
        <Plus className="w-5 h-5" /> Add Exercise
      </button>

      {/* Exercise Picker Modal */}
      {isLibraryOpen && (
        <div className="fixed inset-0 bg-purple-900/30 backdrop-blur-sm z-50 flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] w-full max-w-2xl h-[85vh] flex flex-col shadow-2xl animate-fade-in relative overflow-hidden border border-pink-100">
              <button 
                onClick={() => setIsLibraryOpen(false)} 
                className="absolute top-4 right-4 z-20 p-2 bg-white/80 backdrop-blur-sm rounded-full text-slate-400 hover:text-pink-500 shadow-sm border border-pink-50 transition-colors"
              >
                 <X className="w-5 h-5" />
              </button>

              <div className="p-6 border-b border-pink-50 flex-shrink-0 bg-gradient-to-r from-pink-50/50 to-white">
                  <h3 className="text-2xl font-black text-slate-800">Select Exercise</h3>
                  <p className="text-sm text-pink-400 font-bold">Build your perfect workout</p>
              </div>

              <div className="flex-1 overflow-hidden">
                 <ExerciseLibrary onSelect={handleSelectExercise} />
              </div>

              <div className="p-4 border-t border-pink-50 flex-shrink-0 bg-pink-50/30">
                 <button 
                   onClick={handleAddCustomExercise}
                   className="w-full py-3 bg-white border-2 border-pink-100 hover:border-pink-300 hover:text-pink-600 text-slate-500 rounded-xl font-bold transition-all shadow-sm"
                 >
                    Can't find it? Add custom exercise
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default WorkoutCard;

import React, { useMemo, useState } from 'react';
import { Workout, DailyNutrition, WeightEntry } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer, 
  AreaChart, Area, LineChart, Line
} from 'recharts';
import { Flame, Trophy, TrendingUp, Calendar, Clock, Medal, History, Scale, Plus, X, TrendingDown, Share2, Heart, Sparkles } from 'lucide-react';

interface DashboardProps {
  workouts: Workout[];
  nutritionHistory: DailyNutrition[];
  weightHistory: WeightEntry[];
  setWeightHistory: React.Dispatch<React.SetStateAction<WeightEntry[]>>;
}

const Dashboard: React.FC<DashboardProps> = ({ workouts, nutritionHistory, weightHistory, setWeightHistory }) => {
  const [isWeightModalOpen, setIsWeightModalOpen] = useState(false);
  const [newWeight, setNewWeight] = useState('');

  // --- Derived Statistics ---
  const completedWorkouts = workouts.filter(w => w.completed);
  const totalWorkoutsCount = completedWorkouts.length;

  const totalMinutes = completedWorkouts.reduce((acc, curr) => acc + curr.durationMinutes, 0);
  const averageDuration = totalWorkoutsCount > 0 ? Math.round(totalMinutes / totalWorkoutsCount) : 0;

  const streak = 5; // Mock data for streak logic

  // Weight Stats
  const sortedWeight = [...weightHistory].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  const currentWeight = sortedWeight.length > 0 ? sortedWeight[sortedWeight.length - 1].weight : 0;
  const startWeight = sortedWeight.length > 0 ? sortedWeight[0].weight : 0;
  const weightDiff = currentWeight - startWeight;
  const weightData = sortedWeight.map(w => ({
    date: new Date(w.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
    weight: w.weight
  }));

  const handleAddWeight = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWeight) return;

    const entry: WeightEntry = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      weight: Number(newWeight)
    };

    setWeightHistory(prev => [...prev, entry]);
    setNewWeight('');
    setIsWeightModalOpen(false);
  };

  // Personal Bests Calculation
  const personalBests = useMemo(() => {
    const pbs: Record<string, number> = {};
    completedWorkouts.forEach(workout => {
      workout.exercises.forEach(exercise => {
        exercise.sets.forEach(set => {
          if (set.completed && set.weight > 0) {
            const currentMax = pbs[exercise.name] || 0;
            if (set.weight > currentMax) {
              pbs[exercise.name] = set.weight;
            }
          }
        });
      });
    });
    // Sort by weight desc and take top 5
    return Object.entries(pbs)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 5);
  }, [completedWorkouts]);

  const handleSharePBs = async () => {
    if (personalBests.length === 0) return;

    const pbList = personalBests.map(([name, weight], idx) => `${idx + 1}. ${name}: ${weight}lbs`).join('\n');
    const text = `Hit new Personal Bests on PowHER Lifts! 🏆💪\n\n${pbList}\n\n#PowHERLifts #StrongerEveryDay`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: 'My Personal Bests',
          text: text,
          url: window.location.href
        });
      } catch (err) {
        console.error('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(text);
      alert('Personal Bests copied to clipboard! Share your gains! 🌟');
    }
  };

  // Activity Data for Chart (Mocked based on weekdays)
  const activityData = [
    { day: 'Mon', minutes: 45 },
    { day: 'Tue', minutes: 60 },
    { day: 'Wed', minutes: 0 },
    { day: 'Thu', minutes: 75 },
    { day: 'Fri', minutes: 45 },
    { day: 'Sat', minutes: 90 },
    { day: 'Sun', minutes: 30 },
  ];

  const calorieData = nutritionHistory.map(day => ({
    date: new Date(day.date).toLocaleDateString(undefined, { weekday: 'short' }),
    calories: day.meals.reduce((acc, m) => acc + m.macros.calories, 0),
    protein: day.meals.reduce((acc, m) => acc + m.macros.protein, 0)
  })).slice(-7);

  // If no calorie data, mock it for visual
  const mockCalorieData = [
      { date: 'Mon', calories: 2100, protein: 140 },
      { date: 'Tue', calories: 1950, protein: 130 },
      { date: 'Wed', calories: 2300, protein: 155 },
      { date: 'Thu', calories: 2000, protein: 145 },
      { date: 'Fri', calories: 1850, protein: 125 },
      { date: 'Sat', calories: 2400, protein: 120 },
      { date: 'Sun', calories: 2200, protein: 150 },
  ];

  const StatCard = ({ title, value, icon: Icon, colorClass, subtext }: any) => (
    <div className="bg-white p-6 rounded-[2rem] shadow-lg shadow-pink-100/40 border border-pink-50 flex items-start justify-between transform hover:scale-[1.02] transition-transform">
      <div>
        <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">{title}</p>
        <h3 className="text-3xl font-black text-slate-800">{value}</h3>
        {subtext && <p className="text-xs text-pink-400 font-bold mt-2 flex items-center gap-1">{subtext}</p>}
      </div>
      <div className={`p-3.5 rounded-2xl ${colorClass} shadow-md`}>
        <Icon className="w-6 h-6 text-white" />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in pb-12">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Hello, Gorgeous! ✨</h2>
          <p className="text-slate-500 mt-2 font-medium">Ready to glow and grow today?</p>
        </div>
        <div className="text-right hidden md:block">
           <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Current Focus</p>
           <p className="text-transparent bg-clip-text bg-gradient-to-r from-pink-500 to-purple-500 font-black text-xl">Strength & Toning</p>
        </div>
      </div>

      {/* Top Stats Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Weekly Workouts" 
          value={totalWorkoutsCount} 
          icon={Trophy} 
          colorClass="bg-gradient-to-br from-yellow-400 to-orange-400" 
          subtext="Keep grinding!"
        />
        <StatCard 
          title="Active Minutes" 
          value={totalMinutes} 
          icon={Flame} 
          colorClass="bg-gradient-to-br from-pink-500 to-rose-500" 
          subtext="Total burn time"
        />
        <StatCard 
          title="Current Streak" 
          value={`${streak} Days`} 
          icon={Calendar} 
          colorClass="bg-gradient-to-br from-purple-500 to-indigo-500" 
          subtext="You're on fire!"
        />
        <StatCard 
          title="Avg Protein" 
          value="135g" 
          icon={TrendingUp} 
          colorClass="bg-gradient-to-br from-teal-400 to-emerald-400" 
          subtext="Daily Average"
        />
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Activity Chart */}
        <div className="bg-white p-6 rounded-[2rem] shadow-xl shadow-pink-100/50 border border-pink-50">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-pink-400" /> Activity Overview
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={activityData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#fdf2f8" />
                <XAxis 
                  dataKey="day" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 600 }} 
                  dy={10}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12 }} 
                />
                <RechartsTooltip 
                  cursor={{ fill: '#fdf2f8' }}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(236, 72, 153, 0.1)' }}
                />
                <Bar 
                  dataKey="minutes" 
                  fill="url(#barGradient)" 
                  radius={[8, 8, 8, 8]} 
                />
                <defs>
                  <linearGradient id="barGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="#ec4899" />
                    <stop offset="100%" stopColor="#c084fc" />
                  </linearGradient>
                </defs>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Nutrition Chart */}
        <div className="bg-white p-6 rounded-[2rem] shadow-xl shadow-pink-100/50 border border-pink-50">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
             <Heart className="w-5 h-5 text-rose-400 fill-rose-400" /> Nutrition Trends
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={nutritionHistory.length > 0 ? calorieData : mockCalorieData}>
                <defs>
                  <linearGradient id="colorCalories" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#f472b6" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#f472b6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#fdf2f8" />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 600 }}
                  dy={10} 
                />
                <YAxis hide />
                <RechartsTooltip 
                   contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(236, 72, 153, 0.1)' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="calories" 
                  stroke="#ec4899" 
                  strokeWidth={4} 
                  fillOpacity={1} 
                  fill="url(#colorCalories)" 
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Weight Tracker Section */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-pink-100/50 border border-pink-50 overflow-hidden">
        <div className="p-6 border-b border-pink-50 flex justify-between items-center bg-gradient-to-r from-pink-50/30 to-white">
            <div className="flex items-center gap-3">
                <div className="p-2.5 bg-indigo-50 rounded-xl text-indigo-500 shadow-sm">
                    <Scale className="w-5 h-5" />
                </div>
                <div>
                   <h3 className="font-bold text-slate-800">Weight Tracker</h3>
                   <p className="text-xs text-slate-400 font-medium">Your transformation journey</p>
                </div>
            </div>
            <button 
              onClick={() => setIsWeightModalOpen(true)}
              className="bg-indigo-500 hover:bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all shadow-lg shadow-indigo-200"
            >
                <Plus className="w-4 h-4" /> Log Weight
            </button>
        </div>

        <div className="p-6 grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="space-y-6">
                <div className="bg-slate-50 p-5 rounded-2xl flex items-center justify-between border border-slate-100">
                    <div>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Current</p>
                        <p className="text-3xl font-black text-slate-800">{currentWeight} <span className="text-sm font-bold text-slate-400">lbs</span></p>
                    </div>
                    {weightDiff !== 0 && (
                        <div className={`flex items-center text-sm font-bold px-3 py-1 rounded-full ${weightDiff < 0 ? 'bg-green-100 text-green-600' : 'bg-rose-100 text-rose-500'}`}>
                           {weightDiff < 0 ? <TrendingDown className="w-4 h-4 mr-1" /> : <TrendingUp className="w-4 h-4 mr-1" />}
                           {Math.abs(weightDiff).toFixed(1)} lbs
                        </div>
                    )}
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Start</p>
                        <p className="text-xl font-black text-slate-600">{startWeight} lbs</p>
                    </div>
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                         <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Lost</p>
                         <p className={`text-xl font-black ${weightDiff < 0 ? 'text-green-500' : 'text-slate-600'}`}>
                             {startWeight - currentWeight > 0 ? (startWeight - currentWeight).toFixed(1) : 0} lbs
                         </p>
                    </div>
                </div>
            </div>

            <div className="lg:col-span-2 h-48">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={weightData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#fdf2f8" />
                        <XAxis 
                            dataKey="date" 
                            axisLine={false} 
                            tickLine={false} 
                            tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 600 }}
                            dy={10} 
                        />
                        <YAxis 
                            domain={['dataMin - 5', 'dataMax + 5']} 
                            hide 
                        />
                        <RechartsTooltip 
                            contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(99, 102, 241, 0.2)' }}
                        />
                        <Line 
                            type="monotone" 
                            dataKey="weight" 
                            stroke="#818cf8" 
                            strokeWidth={4} 
                            dot={{ fill: '#818cf8', strokeWidth: 2, r: 4, stroke: '#fff' }}
                            activeDot={{ r: 7, strokeWidth: 0 }}
                        />
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </div>
      </div>

      {/* History & Records Section */}
      <div className="space-y-6">
          <h2 className="text-2xl font-black text-slate-800 pt-4 flex items-center gap-2">
             <History className="w-6 h-6 text-purple-400" /> History & Records
          </h2>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

              {/* Lifetime Stats */}
              <div className="bg-white p-6 rounded-[2rem] shadow-lg shadow-pink-100/40 border border-pink-50 space-y-6">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2">
                      <Sparkles className="w-5 h-5 text-pink-500" /> Lifetime Stats
                  </h3>

                  <div className="space-y-4">
                      <div className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <span className="text-slate-500 text-sm font-semibold">Total Workouts</span>
                          <span className="text-xl font-black text-slate-800">{totalWorkoutsCount}</span>
                      </div>
                      <div className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <span className="text-slate-500 text-sm font-semibold">Avg Duration</span>
                          <span className="text-xl font-black text-slate-800">{averageDuration} min</span>
                      </div>
                      <div className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <span className="text-slate-500 text-sm font-semibold">Total Volume</span>
                          <span className="text-xl font-black text-slate-800">
                             {(completedWorkouts.reduce((acc, w) => 
                                 acc + w.exercises.reduce((eAcc, e) => 
                                     eAcc + e.sets.reduce((sAcc, s) => sAcc + (s.completed ? s.weight * s.reps : 0), 0), 0
                                 ), 0) / 1000).toFixed(1)}k lbs
                          </span>
                      </div>
                  </div>
              </div>

              {/* Personal Bests */}
              <div className="bg-white p-6 rounded-[2rem] shadow-lg shadow-pink-100/40 border border-pink-50">
                  <div className="flex items-center justify-between mb-4">
                      <h3 className="font-bold text-slate-800 flex items-center gap-2">
