interface WorkoutsPageProps {
  workouts: Workout[];
  setWorkouts: React.Dispatch<React.SetStateAction<Workout[]>>;
  onNavigate: (page: Page) => void;
}

const Workouts: React.FC<WorkoutsPageProps> = ({ workouts, setWorkouts, onNavigate }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newWorkoutTitle, setNewWorkoutTitle] = useState('');

  // Filter workouts for the selected date
  // We compare formatted date strings to match day regardless of time
  const dailyWorkouts = workouts.filter(w => {
    const wDate = new Date(w.date);
    return wDate.toDateString() === currentDate.toDateString();
  });

  const handleToggleComplete = (id: string) => {
    setWorkouts(prev => prev.map(w => 
      w.id === id ? { ...w, completed: !w.completed } : w
    ));
  };

  const handleUpdateWorkout = (updatedWorkout: Workout) => {
    setWorkouts(prev => prev.map(w => w.id === updatedWorkout.id ? updatedWorkout : w));
  };

  const handleDeleteWorkout = (id: string) => {
    if (confirm('Are you sure you want to delete this workout?')) {
        setWorkouts(prev => prev.filter(w => w.id !== id));
    }
  };

  const handleCreateWorkout = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWorkoutTitle.trim()) return;

    const newWorkout: Workout = {
      id: Date.now().toString(),
      title: newWorkoutTitle,
      // Create workout for the CURRENTLY SELECTED date
      date: currentDate.toISOString(), 
      durationMinutes: 0,
      completed: false,
      exercises: [
        {
          id: 'ex-1',
          name: 'Squats',
          type: ExerciseType.STRENGTH,
          sets: [{ id: 's-1', reps: 10, weight: 0, completed: false }, { id: 's-2', reps: 10, weight: 0, completed: false }]
        }
      ]
    };

    setWorkouts([newWorkout, ...workouts]);
    setNewWorkoutTitle('');
    setIsModalOpen(false);
