    const text = `Hit new Personal Bests on PowHER Lifts! 🏆💪\n\n${pbList}\n\n#PowHERLifts #StrongerEveryDay`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: 'My Personal Bests',
          text: text,
          url: window.location.href
