            <Sparkles className="w-5 h-5 text-pink-400" /> Activity Overview
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={activityData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#fdf2f8" />
                <XAxis 
                  dataKey="day" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 600 }} 
                  dy={10}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12 }} 
                />
                <RechartsTooltip 
                  cursor={{ fill: '#fdf2f8' }}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(236, 72, 153, 0.1)' }}
                />
                <Bar 
                  dataKey="minutes" 
                  fill="url(#barGradient)" 
                  radius={[8, 8, 8, 8]} 
                />
                <defs>
                  <linearGradient id="barGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="#ec4899" />
                    <stop offset="100%" stopColor="#c084fc" />
                  </linearGradient>
                </defs>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Nutrition Chart */}
        <div className="bg-white p-6 rounded-[2rem] shadow-xl shadow-pink-100/50 border border-pink-50">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
             <Heart className="w-5 h-5 text-rose-400 fill-rose-400" /> Nutrition Trends
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={nutritionHistory.length > 0 ? calorieData : mockCalorieData}>
                <defs>
                  <linearGradient id="colorCalories" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#f472b6" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#f472b6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#fdf2f8" />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 600 }}
                  dy={10} 
                />
                <YAxis hide />
                <RechartsTooltip 
                   contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(236, 72, 153, 0.1)' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="calories" 
                  stroke="#ec4899" 
                  strokeWidth={4} 
                  fillOpacity={1} 
                  fill="url(#colorCalories)" 
