      {/* Weight Tracker Section */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-pink-100/50 border border-pink-50 overflow-hidden">
        <div className="p-6 border-b border-pink-50 flex justify-between items-center bg-gradient-to-r from-pink-50/30 to-white">
            <div className="flex items-center gap-3">
                <div className="p-2.5 bg-indigo-50 rounded-xl text-indigo-500 shadow-sm">
                    <Scale className="w-5 h-5" />
                </div>
                <div>
                   <h3 className="font-bold text-slate-800">Weight Tracker</h3>
                   <p className="text-xs text-slate-400 font-medium">Your transformation journey</p>
                </div>
            </div>
            <button 
              onClick={() => setIsWeightModalOpen(true)}
              className="bg-indigo-500 hover:bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all shadow-lg shadow-indigo-200"
            >
                <Plus className="w-4 h-4" /> Log Weight
            </button>
        </div>

        <div className="p-6 grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="space-y-6">
                <div className="bg-slate-50 p-5 rounded-2xl flex items-center justify-between border border-slate-100">
                    <div>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Current</p>
                        <p className="text-3xl font-black text-slate-800">{currentWeight} <span className="text-sm font-bold text-slate-400">lbs</span></p>
                        {currentEntry && (
                            <p className="text-[10px] text-slate-400 font-bold mt-1 flex items-center gap-1">
                                <Calendar className="w-3 h-3" />
                                {new Date(currentEntry.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                            </p>
                        )}
                    </div>
                    {weightDiff !== 0 && (
                        <div className={`flex items-center text-sm font-bold px-3 py-1 rounded-full ${weightDiff < 0 ? 'bg-green-100 text-green-600' : 'bg-rose-100 text-rose-500'}`}>
                           {weightDiff < 0 ? <TrendingDown className="w-4 h-4 mr-1" /> : <TrendingUp className="w-4 h-4 mr-1" />}
                           {Math.abs(weightDiff).toFixed(1)} lbs
                        </div>
                    )}
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Start</p>
                        <p className="text-xl font-black text-slate-600">{startWeight} lbs</p>
                        {startEntry && (
                            <p className="text-[10px] text-slate-400 font-bold mt-1">
                                {new Date(startEntry.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: '2-digit' })}
                            </p>
                        )}
                    </div>
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                         <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Lost</p>
                         <p className={`text-xl font-black ${weightDiff < 0 ? 'text-green-500' : 'text-slate-600'}`}>
                             {startWeight - currentWeight > 0 ? (startWeight - currentWeight).toFixed(1) : 0} lbs
                         </p>
                    </div>
                </div>
            </div>

            <div className="lg:col-span-2 h-48">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={weightData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#fdf2f8" />
                        <XAxis 
                            dataKey="date" 
                            axisLine={false} 
                            tickLine={false} 
                            tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 600 }}
                            dy={10} 
                        />
                        <YAxis 
                            domain={['dataMin - 5', 'dataMax + 5']} 
                            hide 
                        />
                        <RechartsTooltip 
                            contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(99, 102, 241, 0.2)' }}
                        />
                        <Line 
                            type="monotone" 
                            dataKey="weight" 
                            stroke="#818cf8" 
                            strokeWidth={4} 
                            dot={{ fill: '#818cf8', strokeWidth: 2, r: 4, stroke: '#fff' }}
                            activeDot={{ r: 7, strokeWidth: 0 }}
                        />
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </div>
      </div>

      {/* History & Records Section */}
      <div className="space-y-6">
          <h2 className="text-2xl font-black text-slate-800 pt-4 flex items-center gap-2">
             <History className="w-6 h-6 text-purple-400" /> History & Records
          </h2>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

              {/* Lifetime Stats */}
              <div className="bg-white p-6 rounded-[2rem] shadow-lg shadow-pink-100/40 border border-pink-50 space-y-6">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2">
                      <Sparkles className="w-5 h-5 text-pink-500" /> Lifetime Stats
                  </h3>

                  <div className="space-y-4">
                      <div className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <span className="text-slate-500 text-sm font-semibold">Total Workouts</span>
                          <span className="text-xl font-black text-slate-800">{totalWorkoutsCount}</span>
                      </div>
                      <div className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <span className="text-slate-500 text-sm font-semibold">Avg Duration</span>
                          <span className="text-xl font-black text-slate-800">{averageDuration} min</span>
                      </div>
                      <div className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <span className="text-slate-500 text-sm font-semibold">Total Volume</span>
                          <span className="text-xl font-black text-slate-800">
                             {(completedWorkouts.reduce((acc, w) => 
                                 acc + w.exercises.reduce((eAcc, e) => 
                                     eAcc + e.sets.reduce((sAcc, s) => sAcc + (s.completed ? s.weight * s.reps : 0), 0), 0
                                 ), 0) / 1000).toFixed(1)}k lbs
                          </span>
                      </div>
                  </div>
              </div>

              {/* Personal Bests */}
              <div className="bg-white p-6 rounded-[2rem] shadow-lg shadow-pink-100/40 border border-pink-50">
                  <div className="flex items-center justify-between mb-4">
                      <h3 className="font-bold text-slate-800 flex items-center gap-2">
                          <Medal className="w-5 h-5 text-yellow-400" /> Personal Bests
                      </h3>
                      {personalBests.length > 0 && (
                          <button 
                            onClick={handleSharePBs}
                            className="text-pink-300 hover:text-pink-500 transition-colors p-1"
                            title="Share PBs"
                          >
                            <Share2 className="w-5 h-5" />
                          </button>
                      )}
                  </div>

                  {personalBests.length > 0 ? (
                      <div className="space-y-3">
                          {personalBests.map(([name, weight], index) => (
                              <div key={index} className="flex items-center justify-between group p-2 hover:bg-pink-50/50 rounded-xl transition-colors">
                                  <div className="flex items-center gap-3">
                                      <span className={`
                                          flex items-center justify-center w-8 h-8 rounded-full text-xs font-black shadow-sm
                                          ${index === 0 ? 'bg-yellow-100 text-yellow-600' : 
                                            index === 1 ? 'bg-slate-100 text-slate-600' : 
                                            index === 2 ? 'bg-orange-100 text-orange-600' : 'bg-slate-50 text-slate-400'}
                                      `}>
                                          {index + 1}
                                      </span>
                                      <span className="text-slate-700 font-bold text-sm">{name}</span>
                                  </div>
                                  <span className="font-black text-slate-800 bg-white border border-slate-100 px-3 py-1 rounded-lg text-sm shadow-sm">{weight} lbs</span>
                              </div>
                          ))}
                      </div>
                  ) : (
                      <div className="text-center py-12 text-slate-400 text-sm font-medium">
                          Complete workouts to unlock PBs!
                      </div>
                  )}
              </div>

              {/* Recent History List */}
              <div className="bg-white p-6 rounded-[2rem] shadow-lg shadow-pink-100/40 border border-pink-50">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2 mb-4">
                      <Calendar className="w-5 h-5 text-purple-400" /> Recent History
                  </h3>

                  <div className="space-y-4 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                      {completedWorkouts.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(workout => (
                          <div key={workout.id} className="relative pl-6 py-2 group">
                              <div className="absolute left-0 top-3 w-1.5 h-1.5 rounded-full bg-pink-300 group-hover:scale-150 transition-transform"></div>
                              <div className="absolute left-0.5 top-5 w-0.5 h-full bg-pink-100 -z-10 last:hidden"></div>
                              <h4 className="font-bold text-slate-800 text-sm">{workout.title}</h4>
                              <div className="flex gap-4 mt-1 text-xs text-slate-400 font-semibold">
                                  <span className="flex items-center gap-1"><Calendar className="w-3 h-3" /> {new Date(workout.date).toLocaleDateString()}</span>
                                  <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {workout.durationMinutes} min</span>
                              </div>
                          </div>
                      ))}
                      {completedWorkouts.length === 0 && (
                          <div className="text-center py-12 text-slate-400 text-sm font-medium">
                              No completed workouts yet.
                          </div>
                      )}
                  </div>
              </div>
          </div>
      </div>

      {/* Log Weight Modal */}
      {isWeightModalOpen && (
        <div className="fixed inset-0 bg-purple-900/30 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] w-full max-w-sm shadow-2xl animate-fade-in border border-pink-100 overflow-hidden">
            <div className="p-6 border-b border-pink-50 flex justify-between items-center bg-pink-50/30">
              <h3 className="text-xl font-black text-slate-800">Log Weight</h3>
              <button onClick={() => setIsWeightModalOpen(false)} className="text-slate-400 hover:text-pink-500 transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>
            <form onSubmit={handleAddWeight} className="p-8">
               <label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide text-center">Current Weight</label>
               <div className="relative max-w-[160px] mx-auto">
                 <input 
                    autoFocus
                    type="number"
                    step="0.1"
                    placeholder="0.0"
                    className="w-full px-4 py-4 rounded-2xl bg-slate-50 border-2 border-slate-100 focus:outline-none focus:ring-4 focus:ring-indigo-100 focus:border-indigo-500 text-3xl font-black text-center text-slate-800"
                    value={newWeight}
                    onChange={(e) => setNewWeight(e.target.value)}
                  />
                  <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">lbs</span>
               </div>

               <button 
                 type="submit"
                 disabled={!newWeight}
                 className="w-full mt-8 py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-bold shadow-lg shadow-indigo-200 transition-all disabled:opacity-50 transform hover:scale-[1.02] active:scale-95"
               >
                 Save Entry
               </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Workout, ExerciseType, Page } from '../types';
import WorkoutCard from '../components/WorkoutCard';
import DateSelector from '../components/DateSelector';
import { Plus, X, LayoutDashboard, Sparkles, CalendarDays, Copy, History, Search } from 'lucide-react';

interface WorkoutsPageProps {
  workouts: Workout[];
  setWorkouts: React.Dispatch<React.SetStateAction<Workout[]>>;
  onNavigate: (page: Page) => void;
}

const Workouts: React.FC<WorkoutsPageProps> = ({ workouts, setWorkouts, onNavigate }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isCopyModalOpen, setIsCopyModalOpen] = useState(false);
  const [newWorkoutTitle, setNewWorkoutTitle] = useState('');
  const [copySearch, setCopySearch] = useState('');

  // Filter workouts for the selected date
  const dailyWorkouts = workouts.filter(w => {
    const wDate = new Date(w.date);
    return wDate.toDateString() === currentDate.toDateString();
  });

  // Get unique previous workouts for copying (most recent first)
  const uniquePastWorkouts = workouts
    .filter(w => new Date(w.date).toDateString() !== currentDate.toDateString())
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    .filter((v, i, a) => a.findIndex(t => t.title === v.title) === i);

  const filteredPastWorkouts = uniquePastWorkouts.filter(w => 
    w.title.toLowerCase().includes(copySearch.toLowerCase())
  );

  const handleToggleComplete = (id: string) => {
    setWorkouts(prev => prev.map(w => 
      w.id === id ? { ...w, completed: !w.completed } : w
    ));
  };

  const handleUpdateWorkout = (updatedWorkout: Workout) => {
    setWorkouts(prev => prev.map(w => w.id === updatedWorkout.id ? updatedWorkout : w));
  };

  const handleDeleteWorkout = (id: string) => {
    if (confirm('Are you sure you want to delete this workout?')) {
        setWorkouts(prev => prev.filter(w => w.id !== id));
    }
  };

  const handleCreateWorkout = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWorkoutTitle.trim()) return;

    const newWorkout: Workout = {
      id: Date.now().toString(),
      title: newWorkoutTitle,
      date: currentDate.toISOString(), 
      durationMinutes: 0,
      completed: false,
      exercises: [
        {
          id: 'ex-' + Date.now(),
          name: 'New Exercise',
          type: ExerciseType.STRENGTH,
          sets: [{ id: 's-' + Date.now(), reps: 10, weight: 0, completed: false }]
        }
      ]
    };

    setWorkouts([newWorkout, ...workouts]);
    setNewWorkoutTitle('');
    setIsModalOpen(false);
  };

  const handleCopyWorkout = (sourceWorkout: Workout) => {
    const clonedWorkout: Workout = {
      ...sourceWorkout,
      id: Date.now().toString(),
      date: currentDate.toISOString(),
      completed: false,
      // Deep clone exercises and sets with new IDs
      exercises: sourceWorkout.exercises.map(ex => ({
        ...ex,
        id: 'ex-' + Math.random().toString(36).substr(2, 9),
        sets: ex.sets.map(s => ({
          ...s,
          id: 's-' + Math.random().toString(36).substr(2, 9),
          completed: false
        }))
      }))
    };

    setWorkouts([clonedWorkout, ...workouts]);
    setIsCopyModalOpen(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
        <div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tight">Your Workouts</h2>
            <p className="text-slate-500 font-medium mt-1 flex items-center gap-2">
               <Sparkles className="w-4 h-4 text-pink-500" /> Train, Track, Transform.
            </p>
        </div>
        <div className="flex gap-3">
            <button 
                onClick={() => setIsCopyModalOpen(true)}
                className="flex items-center gap-2 bg-white text-slate-600 border border-slate-200 hover:bg-purple-50 hover:text-purple-600 hover:border-purple-200 px-5 py-3 rounded-2xl font-bold transition-all shadow-sm"
            >
                <Copy className="w-5 h-5" />
                <span className="hidden sm:inline">Copy from History</span>
            </button>
            <button 
                onClick={() => onNavigate(Page.DASHBOARD)}
                className="flex items-center gap-2 bg-white text-slate-600 border border-slate-200 hover:bg-pink-50 hover:text-pink-600 hover:border-pink-200 px-5 py-3 rounded-2xl font-bold transition-all shadow-sm"
            >
                <LayoutDashboard className="w-5 h-5" />
                <span className="hidden sm:inline">Dashboard</span>
            </button>
        </div>
      </div>

      <DateSelector currentDate={currentDate} onDateChange={setCurrentDate} />

      {dailyWorkouts.length > 0 ? (
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-8">
            {dailyWorkouts.map(workout => (
            <WorkoutCard 
                key={workout.id} 
                workout={workout} 
                history={workouts}
                onToggleComplete={handleToggleComplete}
                onUpdateWorkout={handleUpdateWorkout}
                onDeleteWorkout={handleDeleteWorkout}
            />
            ))}

            <button 
                onClick={() => setIsModalOpen(true)}
                className="group flex flex-col items-center justify-center min-h-[300px] rounded-[2rem] border-2 border-dashed border-pink-200 hover:border-pink-400 hover:bg-pink-50/50 transition-all cursor-pointer"
            >
                <div className="w-16 h-16 rounded-full bg-pink-100 flex items-center justify-center text-pink-500 group-hover:scale-110 transition-transform mb-4">
                    <Plus className="w-8 h-8" />
                </div>
                <span className="text-pink-400 font-bold text-lg">Add Another Workout</span>
            </button>
        </div>
      ) : (
        <div className="text-center py-20 bg-white/60 rounded-[2.5rem] border border-pink-50 flex flex-col items-center shadow-lg shadow-pink-100/20">
           <div className="w-24 h-24 bg-gradient-to-br from-pink-100 to-purple-100 rounded-full flex items-center justify-center mb-6 shadow-inner">
              <CalendarDays className="w-10 h-10 text-pink-400" />
           </div>
           <h3 className="text-2xl font-black text-slate-800">Rest Day?</h3>
           <p className="text-slate-400 mt-2 font-medium max-w-md mx-auto">
             No workouts logged for {currentDate.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}. 
             Take a rest or crush a new goal!
           </p>
           <div className="flex flex-col sm:flex-row gap-4 mt-8">
                <button 
                    onClick={() => setIsModalOpen(true)}
                    className="px-8 py-4 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-2xl font-bold shadow-xl shadow-pink-200 transition-all transform hover:-translate-y-1 flex items-center justify-center gap-2"
                >
                    <Plus className="w-5 h-5" />
                    New Plan
                </button>
                <button 
                    onClick={() => setIsCopyModalOpen(true)}
                    className="px-8 py-4 bg-white text-purple-600 border-2 border-purple-100 hover:bg-purple-50 rounded-2xl font-bold transition-all transform hover:-translate-y-1 flex items-center justify-center gap-2"
                >
                    <History className="w-5 h-5" />
                    Copy from History
                </button>
           </div>
        </div>
      )}

      {/* New Workout Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-purple-900/30 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] w-full max-w-md shadow-2xl transform transition-all border border-pink-100 overflow-hidden animate-fade-in">
            <div className="p-6 border-b border-pink-50 flex justify-between items-center bg-gradient-to-r from-pink-50/50 to-white">
              <h3 className="text-2xl font-black text-slate-800">New Plan</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-pink-500 transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>
            <form onSubmit={handleCreateWorkout} className="p-8">
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">Workout Name</label>
                  <input 
                    type="text" 
                    placeholder="e.g. Leg Day Destroyer 🍑" 
                    className="w-full px-5 py-4 rounded-2xl bg-slate-50 border-2 border-slate-100 focus:outline-none focus:ring-4 focus:ring-pink-100 focus:border-pink-400 transition-all font-bold text-lg text-slate-800 placeholder-slate-300"
                    value={newWorkoutTitle}
                    onChange={(e) => setNewWorkoutTitle(e.target.value)}
                    autoFocus
                  />
                </div>
                <div>
                    <label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">Date</label>
                    <div className="px-5 py-4 rounded-2xl bg-slate-50 border-2 border-slate-100 text-slate-600 font-bold">
                        {currentDate.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}
                    </div>
                </div>
              </div>
              <div className="mt-10 flex gap-3">
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 px-4 py-3.5 rounded-2xl border-2 border-slate-100 text-slate-500 font-bold hover:bg-slate-50 hover:text-slate-700 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  disabled={!newWorkoutTitle.trim()}
                  className="flex-1 px-4 py-3.5 rounded-2xl bg-gradient-to-r from-pink-500 to-rose-500 text-white font-bold hover:shadow-lg hover:shadow-pink-200 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:-translate-y-0.5"
                >
                  Start Planning
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Copy Workout Modal */}
      {isCopyModalOpen && (
        <div className="fixed inset-0 bg-purple-900/30 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2rem] w-full max-w-lg h-[80vh] flex flex-col shadow-2xl animate-fade-in border border-purple-100 overflow-hidden">
            <div className="p-6 border-b border-purple-50 flex justify-between items-center bg-purple-50/30">
              <div>
                <h3 className="text-2xl font-black text-slate-800">Copy Workout</h3>
                <p className="text-sm text-purple-400 font-bold">Repeat a previous routine</p>
              </div>
              <button onClick={() => setIsCopyModalOpen(false)} className="text-slate-400 hover:text-purple-500 transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6 border-b border-slate-50">
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                <input 
                  type="text"
                  placeholder="Search previous workouts..."
                  className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-4 focus:ring-purple-100 focus:border-purple-300 font-bold"
                  value={copySearch}
                  onChange={(e) => setCopySearch(e.target.value)}
                />
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
              {filteredPastWorkouts.length > 0 ? (
                filteredPastWorkouts.map(workout => (
                  <button
                    key={workout.id}
                    onClick={() => handleCopyWorkout(workout)}
                    className="w-full text-left bg-white p-5 rounded-2xl border border-slate-100 hover:border-purple-300 hover:shadow-md hover:shadow-purple-50 transition-all group"
                  >
                    <div className="flex justify-between items-start">
                      <div>
                        <h4 className="font-black text-slate-800 text-lg group-hover:text-purple-600 transition-colors">{workout.title}</h4>
                        <div className="flex gap-4 mt-2 text-xs font-bold text-slate-400 uppercase tracking-wider">
                           <span className="flex items-center gap-1"><History className="w-3 h-3" /> Last done {new Date(workout.date).toLocaleDateString()}</span>
                           <span className="flex items-center gap-1"><Copy className="w-3 h-3" /> {workout.exercises.length} exercises</span>
                        </div>
                      </div>
                      <div className="p-2 bg-purple-50 text-purple-500 rounded-xl group-hover:bg-purple-500 group-hover:text-white transition-all">
                        <Plus className="w-5 h-5" />
                      </div>
                    </div>
                  </button>
                ))
              ) : (
                <div className="text-center py-12">
                   <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
                      <History className="w-8 h-8 text-slate-200" />
                   </div>
                   <p className="text-slate-400 font-bold">No previous workouts found.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Workouts;

import React, { useState } from 'react';
import { Meal, DailyNutrition, MealCategory, Page } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';
import { Plus, Coffee, Sun, Moon, Apple, X, ChevronDown, LayoutDashboard, Utensils, Trash2, Copy, History, Search, Clock } from 'lucide-react';
import { generateMealIdea } from '../services/geminiService';
import DateSelector from '../components/DateSelector';

interface NutritionProps {
  history: DailyNutrition[];
  setHistory: React.Dispatch<React.SetStateAction<DailyNutrition[]>>;
  onNavigate: (page: Page) => void;
}

const Nutrition: React.FC<NutritionProps> = ({ history, setHistory, onNavigate }) => {
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [isMealModalOpen, setIsMealModalOpen] = useState(false);
  const [isCopyModalOpen, setIsCopyModalOpen] = useState(false);
  const [copySearch, setCopySearch] = useState('');

  const getFormattedDate = (date: Date) => {
    const offset = date.getTimezoneOffset();
    const d = new Date(date.getTime() - (offset*60*1000));
    return d.toISOString().split('T')[0];
  };

  const currentDateString = getFormattedDate(selectedDate);
  const dayEntry = history.find(d => d.date.split('T')[0] === currentDateString) || { date: currentDateString, meals: [], waterIntakeMl: 0 };

  const totalCalories = dayEntry.meals.reduce((acc, m) => acc + m.macros.calories, 0);
  const totalProtein = dayEntry.meals.reduce((acc, m) => acc + m.macros.protein, 0);
  const totalCarbs = dayEntry.meals.reduce((acc, m) => acc + m.macros.carbs, 0);
  const totalFats = dayEntry.meals.reduce((acc, m) => acc + m.macros.fats, 0);

  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<string | null>(null);

  const [newMeal, setNewMeal] = useState<{
    name: string;
    category: MealCategory;
    calories: string;
    protein: string;
    carbs: string;
    fats: string;
  }>({
    name: '',
    category: 'Breakfast',
    calories: '',
    protein: '',
    carbs: '',
    fats: ''
  });

  // Get unique past meals
  const uniquePastMeals = history
    .flatMap(day => day.meals)
    .filter((v, i, a) => a.findIndex(t => t.name === v.name) === i)
    .sort((a, b) => b.id.localeCompare(a.id)); // Simple sorting

  const filteredPastMeals = uniquePastMeals.filter(m => 
    m.name.toLowerCase().includes(copySearch.toLowerCase())
  );

  const getAiSuggestion = async () => {
    setIsAiLoading(true);
    setAiSuggestion(null);
    try {
        const suggestion = await generateMealIdea(500, 'lunch');
        setAiSuggestion(suggestion);
    } catch (e) {
        setAiSuggestion("Could not generate recipe.");
    } finally {
        setIsAiLoading(false);
    }
  };

  const handleAddMealSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMeal.name || !newMeal.calories) return;

    const mealToAdd: Meal = {
        id: Date.now().toString(),
        name: newMeal.name,
        category: newMeal.category,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        macros: {
            calories: Number(newMeal.calories),
            protein: Number(newMeal.protein) || 0,
            carbs: Number(newMeal.carbs) || 0,
            fats: Number(newMeal.fats) || 0
        },
        ingredients: []
    };

    addMealToState(mealToAdd);
    setNewMeal({ name: '', category: 'Breakfast', calories: '', protein: '', carbs: '', fats: '' });
    setIsMealModalOpen(false);
  };

  const addMealToState = (meal: Meal) => {
    const exists = history.find(h => h.date.split('T')[0] === currentDateString);
    if (exists) {
        setHistory(prev => prev.map(h => 
            h.date.split('T')[0] === currentDateString ? { ...h, meals: [...h.meals, meal] } : h
        ));
    } else {
        setHistory([...history, { date: currentDateString, meals: [meal], waterIntakeMl: 0 }]);
    }
  };

  const handleCopyMeal = (sourceMeal: Meal) => {
    const clonedMeal: Meal = {
      ...sourceMeal,
      id: Date.now().toString(),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    addMealToState(clonedMeal);
    setIsCopyModalOpen(false);
  };

  const handleDeleteMeal = (mealId: string) => {
    if (confirm('Are you sure you want to remove this meal?')) {
        setHistory(prev => prev.map(day => {
            if (day.date.split('T')[0] === currentDateString) {
                return {
                    ...day,
                    meals: day.meals.filter(m => m.id !== mealId)
                };
            }
            return day;
        }));
    }
  };

  const macroData = [
    { name: 'Protein', value: totalProtein, color: '#2dd4bf' },
    { name: 'Carbs', value: totalCarbs, color: '#facc15' },
    { name: 'Fats', value: totalFats, color: '#fb7185' },
  ];

  const chartData = macroData.every(d => d.value === 0) 
    ? [{ name: 'Empty', value: 1, color: '#f3f4f6' }] 
    : macroData;

  const categories: MealCategory[] = ['Breakfast', 'Lunch', 'Dinner', 'Snack'];

  return (
    <div className="space-y-6 relative">
       <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
           <div>
              <h2 className="text-4xl font-black text-slate-900 tracking-tight">Nutrition Log</h2>
              <p className="text-slate-500 mt-1 font-medium">Fuel your body right. 🌱</p>
           </div>
           <div className="flex gap-3">
              <button 
                  onClick={() => setIsCopyModalOpen(true)}
                  className="flex items-center gap-2 bg-white text-slate-600 border border-slate-200 hover:bg-teal-50 hover:text-teal-600 hover:border-teal-200 px-5 py-3 rounded-2xl font-bold transition-all shadow-sm"
              >
                  <Copy className="w-5 h-5" />
                  <span className="hidden sm:inline">Copy Previous</span>
              </button>
              <button 
                  onClick={() => onNavigate(Page.DASHBOARD)}
                  className="flex items-center gap-2 bg-white text-slate-600 border border-slate-200 hover:bg-pink-50 hover:text-pink-600 hover:border-pink-200 px-5 py-3 rounded-2xl font-bold transition-all shadow-sm"
              >
                  <LayoutDashboard className="w-5 h-5" />
                  <span className="hidden sm:inline">Dashboard</span>
              </button>
           </div>
       </div>

       <DateSelector currentDate={selectedDate} onDateChange={setSelectedDate} />

       <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 space-y-8">
             <div className="bg-white p-8 rounded-[2rem] shadow-xl shadow-pink-100/50 border border-pink-50 flex flex-col items-center">
                <h3 className="text-xl font-black text-slate-800 w-full text-left mb-6 flex items-center gap-2">
                   <Utensils className="w-5 h-5 text-pink-400" /> Daily Calories
                </h3>
                <div className="w-56 h-56 relative">
                   <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                         <Pie
                           data={chartData}
                           innerRadius={70}
                           outerRadius={90}
                           paddingAngle={5}
                           dataKey="value"
                           stroke="none"
                           cornerRadius={8}
                         >
                           {chartData.map((entry, index) => (
                             <Cell key={`cell-${index}`} fill={entry.color} />
                           ))}
                         </Pie>
                         <Tooltip />
                      </PieChart>
                   </ResponsiveContainer>
                   <div className="absolute inset-0 flex items-center justify-center flex-col pointer-events-none">
                      <span className="text-4xl font-black text-slate-800">{totalCalories}</span>
                      <span className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">kcal</span>
                   </div>
                </div>
                <div className="w-full mt-8 space-y-4">
                   <div className="flex justify-between items-center text-sm p-3 bg-teal-50 rounded-xl border border-teal-100">
                      <span className="flex items-center gap-2 text-teal-700 font-bold">
                        <div className="w-3 h-3 rounded-full bg-teal-400"></div> Protein
                      </span>
                      <span className="font-black text-teal-800">{totalProtein}g</span>
                   </div>
                   <div className="flex justify-between items-center text-sm p-3 bg-yellow-50 rounded-xl border border-yellow-100">
                      <span className="flex items-center gap-2 text-yellow-700 font-bold">
                        <div className="w-3 h-3 rounded-full bg-yellow-400"></div> Carbs
                      </span>
                      <span className="font-black text-yellow-800">{totalCarbs}g</span>
                   </div>
                   <div className="flex justify-between items-center text-sm p-3 bg-rose-50 rounded-xl border border-rose-100">
                      <span className="flex items-center gap-2 text-rose-700 font-bold">
                        <div className="w-3 h-3 rounded-full bg-rose-400"></div> Fats
                      </span>
                      <span className="font-black text-rose-800">{totalFats}g</span>
                   </div>
                </div>
             </div>

             <div className="bg-gradient-to-br from-indigo-500 to-purple-600 p-8 rounded-[2rem] text-white shadow-xl shadow-indigo-200">
                <h3 className="font-black text-xl mb-2">Need Inspiration? 💡</h3>
                <p className="text-indigo-100 text-sm mb-6 font-medium">Let our AI Chef suggest a perfect high-protein meal for you.</p>
                <button 
                  onClick={getAiSuggestion}
                  disabled={isAiLoading}
                  className="w-full bg-white text-indigo-600 hover:bg-indigo-50 py-3 rounded-xl text-sm font-bold transition-all shadow-md flex items-center justify-center gap-2"
                >
                   {isAiLoading ? 'Thinking...' : 'Get Recipe Idea'}
                </button>
                {aiSuggestion && (
                    <div className="mt-6 p-4 bg-black/20 rounded-xl text-xs leading-relaxed max-h-48 overflow-y-auto custom-scrollbar font-medium">
                        {aiSuggestion}
                    </div>
                )}
             </div>
          </div>

          <div className="lg:col-span-2 space-y-8">
              <div className="flex justify-between items-center">
                  <h3 className="text-2xl font-black text-slate-800">Meals</h3>
                  <button 
                    onClick={() => setIsMealModalOpen(true)}
                    className="bg-pink-100 hover:bg-pink-200 text-pink-600 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-colors"
                  >
                      <Plus className="w-4 h-4" /> Log Meal
                  </button>
              </div>

              <div className="space-y-8">
                  {categories.map((category) => {
                    const mealsInCategory = dayEntry.meals.filter(m => m.category === category);
                    return (
                      <div key={category} className="space-y-4">
                        <div className="flex items-center gap-3">
                          <span className={`w-3 h-3 rounded-full ${category === 'Breakfast' ? 'bg-orange-300' : category === 'Lunch' ? 'bg-yellow-300' : category === 'Dinner' ? 'bg-indigo-300' : 'bg-pink-300'}`}></span>
                          <span className="text-slate-500 font-bold text-sm uppercase tracking-widest">{category}</span>
                        </div>

                        {mealsInCategory.length === 0 ? (
                           <div className="border-2 border-dashed border-slate-100 rounded-2xl p-6 text-center text-slate-300 text-sm font-bold">
                              No {category.toLowerCase()} logged yet.
                           </div>
                        ) : (
                          <div className="space-y-3">
                             {mealsInCategory.map((meal) => (
                                <div key={meal.id} className="bg-white p-5 rounded-2xl shadow-sm border border-slate-50 flex items-center justify-between group hover:border-pink-200 hover:shadow-md hover:shadow-pink-50 transition-all">
                                    <div className="flex items-center gap-5">
                                        <div className="p-3.5 bg-slate-50 text-slate-400 rounded-2xl group-hover:bg-pink-50 group-hover:text-pink-500 transition-colors">
                                            <UtensilIconForTime category={meal.category} />
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-slate-800 text-lg">{meal.name}</h4>
                                            <p className="text-xs text-slate-400 font-bold mt-1">{meal.time} • <span className="text-pink-500">{meal.macros.calories} kcal</span></p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <div className="hidden sm:flex gap-3 text-xs font-bold text-slate-500">
                                            <div className="text-center min-w-[60px] p-2 bg-slate-50 rounded-xl">
                                                <span className="block text-teal-500 text-sm">{meal.macros.protein}g</span>
                                                <span className="text-[10px] text-slate-300">PRO</span>
                                            </div>
                                            <div className="text-center min-w-[60px] p-2 bg-slate-50 rounded-xl">
                                                <span className="block text-yellow-500 text-sm">{meal.macros.carbs}g</span>
                                                <span className="text-[10px] text-slate-300">CARB</span>
                                            </div>
                                            <div className="text-center min-w-[60px] p-2 bg-slate-50 rounded-xl">
                                                <span className="block text-rose-500 text-sm">{meal.macros.fats}g</span>
                                                <span className="text-[10px] text-slate-300">FAT</span>
                                            </div>
                                        </div>
                                        <button 
                                            onClick={() => handleDeleteMeal(meal.id)}
                                            className="p-2 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-full transition-colors ml-2"
                                            title="Delete Meal"
                                        >
                                            <Trash2 className="w-5 h-5" />
                                        </button>
                                    </div>
                                </div>
                             ))}
                          </div>
                        )}
                      </div>
                    );
                  })}
              </div>
          </div>
       </div>

       {/* Meal Modal */}
       {isMealModalOpen && (
         <div className="fixed inset-0 bg-purple-900/30 backdrop-blur-sm z-50 flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] w-full max-w-md shadow-2xl animate-fade-in border border-pink-100 overflow-hidden">
             <div className="p-6 border-b border-pink-50 flex justify-between items-center bg-pink-50/30">
               <h3 className="text-xl font-black text-slate-800">Log Meal</h3>
               <button onClick={() => setIsMealModalOpen(false)} className="text-slate-400 hover:text-pink-500 transition-colors">
                 <X className="w-6 h-6" />
               </button>
             </div>
             <form onSubmit={handleAddMealSubmit} className="p-8">
                <div className="space-y-6">
                   <div className="grid grid-cols-2 gap-4">
                      <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Category</label>
                        <div className="relative">
                          <select 
                             value={newMeal.category}
                             onChange={(e) => setNewMeal({ ...newMeal, category: e.target.value as MealCategory })}
                             className="w-full px-5 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-4 focus:ring-pink-100 focus:border-pink-400 appearance-none bg-white font-bold text-slate-700"
                          >
                            <option value="Breakfast">Breakfast ☀️</option>
                            <option value="Lunch">Lunch 🥗</option>
                            <option value="Dinner">Dinner 🌙</option>
                            <option value="Snack">Snack 🍎</option>
                          </select>
                          <ChevronDown className="w-5 h-5 text-slate-400 absolute right-4 top-3.5 pointer-events-none" />
                        </div>
                      </div>
                   </div>

                   <div>
                     <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Meal Name</label>
                     <input 
                       required
                       type="text"
                       placeholder="e.g. Avocado Toast"
                       className="w-full px-5 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-4 focus:ring-pink-100 focus:border-pink-400 font-bold text-slate-700 placeholder-slate-300"
                       value={newMeal.name}
                       onChange={(e) => setNewMeal({ ...newMeal, name: e.target.value })}
                     />
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                     <div>
                       <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Calories</label>
                       <input 
                         required
                         type="number"
                         placeholder="0"
                         className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-4 focus:ring-pink-100 focus:border-pink-400 font-bold text-slate-700"
                         value={newMeal.calories}
                         onChange={(e) => setNewMeal({ ...newMeal, calories: e.target.value })}
                       />
                     </div>
                     <div>
                       <label className="block text-xs font-bold text-teal-400 uppercase tracking-widest mb-2">Protein (g)</label>
                       <input 
                         type="number"
                         placeholder="0"
                         className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-4 focus:ring-teal-100 focus:border-teal-400 font-bold text-slate-700"
                         value={newMeal.protein}
                         onChange={(e) => setNewMeal({ ...newMeal, protein: e.target.value })}
                       />
                     </div>
                     <div>
                       <label className="block text-xs font-bold text-yellow-400 uppercase tracking-widest mb-2">Carbs (g)</label>
                       <input 
                         type="number"
                         placeholder="0"
                         className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-4 focus:ring-yellow-100 focus:border-yellow-400 font-bold text-slate-700"
                         value={newMeal.carbs}
                         onChange={(e) => setNewMeal({ ...newMeal, carbs: e.target.value })}
                       />
                     </div>
                     <div>
                       <label className="block text-xs font-bold text-rose-400 uppercase tracking-widest mb-2">Fats (g)</label>
                       <input 
                         type="number"
                         placeholder="0"
                         className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-4 focus:ring-rose-100 focus:border-rose-400 font-bold text-slate-700"
                         value={newMeal.fats}
                         onChange={(e) => setNewMeal({ ...newMeal, fats: e.target.value })}
                       />
                     </div>
                   </div>
                </div>
                <div className="mt-10">
                   <button 
                     type="submit"
                     className="w-full py-4 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-600 hover:to-rose-600 text-white rounded-2xl font-bold shadow-lg shadow-pink-200 transition-all transform hover:-translate-y-0.5"
                   >
                     Add Meal
                   </button>
                </div>
             </form>
           </div>
         </div>
       )}

       {/* Copy Meal Modal */}
       {isCopyModalOpen && (
         <div className="fixed inset-0 bg-teal-900/30 backdrop-blur-sm z-50 flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] w-full max-w-lg h-[80vh] flex flex-col shadow-2xl animate-fade-in border border-teal-100 overflow-hidden">
             <div className="p-6 border-b border-teal-50 flex justify-between items-center bg-teal-50/30">
               <div>
                 <h3 className="text-2xl font-black text-slate-800">Copy Meal</h3>
                 <p className="text-sm text-teal-400 font-bold">Repeat a previous favorite</p>
               </div>
               <button onClick={() => setIsCopyModalOpen(false)} className="text-slate-400 hover:text-teal-500 transition-colors">
                 <X className="w-6 h-6" />
               </button>
             </div>

             <div className="p-6 border-b border-slate-50">
               <div className="relative">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                 <input 
                   type="text"
                   placeholder="Search previous meals..."
                   className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-4 focus:ring-teal-100 focus:border-teal-300 font-bold"
                   value={copySearch}
                   onChange={(e) => setCopySearch(e.target.value)}
                 />
               </div>
             </div>

             <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
               {filteredPastMeals.length > 0 ? (
                 filteredPastMeals.map(meal => (
                   <button
                     key={meal.id}
                     onClick={() => handleCopyMeal(meal)}
                     className="w-full text-left bg-white p-5 rounded-2xl border border-slate-100 hover:border-teal-300 hover:shadow-md hover:shadow-teal-50 transition-all group"
                   >
                     <div className="flex justify-between items-center">
                       <div className="flex items-center gap-4">
                         <div className="p-3 bg-slate-50 text-slate-400 rounded-xl group-hover:bg-teal-50 group-hover:text-teal-500 transition-all">
                           <UtensilIconForTime category={meal.category} />
                         </div>
                         <div>
                           <h4 className="font-black text-slate-800 text-lg group-hover:text-teal-600 transition-colors">{meal.name}</h4>
                           <div className="flex gap-3 mt-1 text-xs font-bold text-slate-400">
                              <span className="text-teal-500">{meal.macros.calories} kcal</span>
                              <span>•</span>
                              <span>{meal.macros.protein}g Protein</span>
                              <span>•</span>
                              <span className="uppercase tracking-wide">{meal.category}</span>
                           </div>
                         </div>
                       </div>
                       <div className="p-2 bg-teal-50 text-teal-500 rounded-xl group-hover:bg-teal-500 group-hover:text-white transition-all">
                         <Plus className="w-5 h-5" />
                       </div>
                     </div>
                   </button>
                 ))
               ) : (
                 <div className="text-center py-12">
                    <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
                       <History className="w-8 h-8 text-slate-200" />
                    </div>
                    <p className="text-slate-400 font-bold">No previous meals found.</p>
                 </div>
               )}
             </div>
           </div>
         </div>
       )}
    </div>
  );
};

const UtensilIconForTime = ({ category }: { category: MealCategory }) => {
    switch(category) {
      case 'Breakfast': return <Sun className="w-5 h-5" />;
      case 'Lunch': return <Sun className="w-5 h-5" />;
      case 'Dinner': return <Moon className="w-5 h-5" />;
      default: return <Apple className="w-5 h-5" />;
    }
};

export default Nutrition;
